    F = _ik_fi()
    O = F.fi_k13_tara(V, F.FI_K16_GEVSEK)
    return pd.DataFrame({"sembol": O.sembol.values, "gun": pd.to_datetime(O.bilgi).values}) if len(O) \
        else pd.DataFrame(columns=["sembol", "gun"])


